import AVFoundation
import XCTest
@testable import Zapp

/// Petit flux TS (H.264 + AAC, 1,2 s) généré avec ffmpeg, converti en MP4 sans réencodage.
final class RemuxerTests: XCTestCase {
    private static let sample = ""

    func testSplitsAnnexBNalUnits() {
        let data = Data([0, 0, 0, 1, 0x67, 1, 2, 0, 0, 1, 0x68, 3, 0, 0, 1, 0x65, 9, 9])
        let units = TSRemuxer.nalUnits(data)
        XCTAssertEqual(units.count, 3)
        XCTAssertEqual(units[0], Data([0x67, 1, 2]))
        XCTAssertEqual(units[1], Data([0x68, 3]))
        XCTAssertEqual(units[2], Data([0x65, 9, 9]))
    }

    func testConvertsTransportStreamToPlayableMP4() async throws {
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let input = folder.appendingPathComponent("test.ts")
        try XCTUnwrap(Data(base64Encoded: Self.sample)).write(to: input)
        let output = folder.appendingPathComponent("test.mp4")

        try TSRemuxer(input: input, output: output).run()

        let asset = AVURLAsset(url: output)
        let playable = try await asset.load(.isPlayable)
        XCTAssertTrue(playable)
        let video = try await asset.loadTracks(withMediaType: .video)
        let audio = try await asset.loadTracks(withMediaType: .audio)
        XCTAssertEqual(video.count, 1)
        XCTAssertEqual(audio.count, 1)
        let duration = try await asset.load(.duration).seconds
        XCTAssertGreaterThan(duration, 0.8)
    }
}
